import csv
import re

EMAIL = r"[^@\s]+@[^@\s]+\.[^@\s]+"

def clean_name(text):
    return " ".join(text.split()).title()

def clean_email(text):
    email = text.strip().lower()
    if re.fullmatch(EMAIL, email):
        return email
    return None

problems = 0
with open("contacts.csv", newline="") as src, open("contacts_clean.csv", "w", newline="") as out:
    writer = csv.DictWriter(out, fieldnames=["name", "email"])
    writer.writeheader()
    for row in csv.DictReader(src):
        email = clean_email(row["email"])
        if email is None:
            problems = problems + 1
        writer.writerow({"name": clean_name(row["name"]), "email": email})

print("Done.", problems, "rows had a bad email. Your original file was not changed.")

